                end += 1
        if depth:
            stop("UNTERMINATED_BLOCK_COMMENT")
    else:
        literal = re.match(r'(?:br|cr|r)(#{0,255})"', source[i:])
        if literal:
            terminator = '"' + literal.group(1)
            close = source.find(terminator, i + literal.end())
            if close < 0:
                stop("UNTERMINATED_RAW_STRING")
            end = close + len(terminator)
        elif source[i] == '"':
            end = i + 1
            while end < n:
                if source[end] == "\\":
                    end += 2
