def closing(open_at):
    pairs = {"{": "}", "(": ")", "[": "]"}
    stack = [pairs[code[open_at]]]
    cursor = open_at + 1
    while cursor < n and stack:
        char = code[cursor]
        if char in pairs:
            stack.append(pairs[char])
        elif char in "})]":
            if char != stack.pop():
                stop("UNBALANCED_DECLARATION", offset=cursor)
        cursor += 1
    if stack:
        stop("UNCLOSED_DECLARATION", offset=open_at)
    return cursor

def attributes(start):
    cursor = start
    while True:
        end = cursor
        while end and code[end - 1].isspace():
            end -= 1
        if not end or code[end - 1] != "]":
            return cursor
        depth, left = 1, end - 2
        while left >= 0 and depth:
